if(advertisedRate && !base.rate_values.includes(advertisedRate)) throw new Error('The advertised rate is not a literal source choice.');
const rateQuote=advertisedRate?(base.rate_quotes.find(q=>q===parsed.rate_source_quote && q.includes(advertisedRate))||base.rate_quotes.find(q=>q.includes(advertisedRate))):null;
if(advertisedRate && !rateQuote) throw new Error('The advertised rate has no literal source quote.');
const rules={version:'1',employment:source.employment.kind==='required'?source.employment:{kind:'unknown'},age:source.age.kind==='required'?source.age:{kind:'unknown'},monthly_income:source.monthly_income.kind==='required'?source.monthly_income:{kind:'unknown'},credit_score:source.credit_score.kind==='unknown'?{kind:'unknown'}:source.credit_score,incomplete_eligibility:'review'};
return {json:{product_id:base.product_id,source_excerpt:base.source_excerpt,provider:'openrouter',model_name:base.request.model,rules,advertised_rate:advertisedRate,rate_source_quote:rateQuote,evidence:(parsed.evidence||[]).slice(0,12),limitations:(parsed.limitations||[]).slice(0,12)}};

